var st=L.newGame(rng),guard=0;
while(!st.matchOver&&guard<5000){
  guard++;
  if(st.phase==='hokm'){
    st.hakam=L.determineHakam(st);
    L.dealRest(st,L.aiPickHokm(st,st.hakam));
  }else{
    var pi=st.turn,card=L.aiChoose(st,pi);
