function evaluate5(cs){
 var s0=cs[0].s,flush=true,cnt={},i,k;
 for(i=0;i<5;i++){if(cs[i].s!==s0)flush=false;cnt[cs[i].r]=(cnt[cs[i].r]||0)+1}
