function fire(st,rr,cc){
 st.t[rr][cc]=true;
 var res=shoot(st.g,rr,cc);
 if(res.hit){var nb=[[-1,0],[1,0],[0,-1],[0,1]];for(var i=0;i<4;i++){var y=rr+nb[i][0],x=cc+nb[i][1];if(y>=0&&y<10&&x>=0&&x<10&&!st.t[y][x])st.tg.push([y,x])}}
