 for(s=1;s<=steps;s++){
  if(dc<0){lr=v.r;lc=v.c-s;}else if(dc>0){lr=v.r;lc=v.c+v.len-1+s;}
  else if(dr<0){lr=v.r-s;lc=v.c;}else{lr=v.r+v.len-1+s;lc=v.c;}
  if(lr<0||lr>=st.h||lc<0||lc>=st.w)return false;
