  for (var i = 0; i < k; i++) {
    var j = i + Math.floor(rng() * (pool.length - i));
    var tmp = pool[i]; pool[i] = pool[j]; pool[j] = tmp;
  }
  var qs = pool.slice(0, k), brute = false;
  for (var a = 0; a < qs.length && !brute; a++)
