T.ok(L.canPlay(C(0,13),C(1,1)),'K over A wraps');
T.ok(L.canPlay(C(1,1),C(0,13)),'A over K wraps');
T.ok(L.canPlay(C(2,2),C(0,1)),'2 over A');
